"""Build a portable, offline comparison gallery from completed scene renders."""
import argparse,json,shutil,subprocess,tempfile
from pathlib import Path
from PIL import Image

PAGE=r'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>bae · Rooms, refined</title>
<style>
:root{color-scheme:dark;--bg:#0c121b;--panel:#151e2a;--text:#e8eef6;--muted:#93a5bb;--mint:#71efce;--orange:#ffbd8c}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:16px/1.55 system-ui,sans-serif}main{max-width:1440px;margin:auto;padding:32px 40px}nav{display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid #273344;padding-bottom:22px}.logo{font-size:34px;font-weight:800;color:var(--mint);letter-spacing:-2px}nav span:last-child{color:var(--muted);font-size:13px;letter-spacing:2px}.intro{display:grid;grid-template-columns:1.5fr 1fr;gap:50px;padding:38px 0 24px}h1{font-size:clamp(30px,4vw,56px);font-weight:600;letter-spacing:-2px;line-height:1.08;margin:0 0 18px}p{color:var(--muted);margin:0}.eyebrow{color:var(--mint);font-size:12px;letter-spacing:2px;margin-bottom:15px}.stats{display:flex;align-items:center;justify-content:space-between;gap:24px}.stat strong{font-size:36px;font-weight:500;display:block}.stat span{font-size:12px;color:var(--muted)}button,select{font:inherit;color:inherit;background:#172231;border:1px solid #304054;border-radius:8px;padding:10px 15px;cursor:pointer}button[aria-pressed=true]{color:var(--mint);border-color:var(--mint);background:#18352f}.scenes{display:flex;gap:10px;flex-wrap:wrap;margin:6px 0 20px}.compare{position:relative;width:100%;aspect-ratio:4/3;background:#101722;overflow:hidden;border:1px solid #29394b;border-radius:12px}.compare img{position:absolute;width:100%;height:100%;object-fit:contain;inset:0}.compare .after{clip-path:inset(0 0 0 var(--split,50%))}.divider{position:absolute;left:var(--split,50%);top:0;bottom:0;width:2px;background:var(--mint);pointer-events:none}.handle{position:absolute;top:50%;left:var(--split,50%);transform:translate(-50%,-50%);border:2px solid var(--mint);border-radius:50%;background:#142c29;padding:8px;color:var(--mint);pointer-events:none}.drag{position:absolute;inset:0;width:100%;height:100%;margin:0;opacity:0;cursor:ew-resize}.tag{position:absolute;top:18px;padding:6px 12px;background:#0c121bdb;border-radius:5px;font-size:12px;letter-spacing:1px;pointer-events:none}.tag.left{left:18px;color:var(--orange)}.tag.right{right:18px;color:var(--mint)}.workspace{display:grid;grid-template-columns:minmax(0,2.4fr) minmax(250px,1fr);gap:22px}.aside{background:var(--panel);border-radius:12px;padding:24px;display:flex;flex-direction:column;gap:24px}.aside h2{font-size:17px;font-weight:500;margin:0 0 8px}.aside p{font-size:13px}.key{display:flex;gap:14px;font-size:11px;color:var(--muted);flex-wrap:wrap}.key b{display:inline-block;width:8px;height:8px;border-radius:50%;margin-right:5px}canvas{width:100%;aspect-ratio:1.15;background:#101822;border-radius:8px}.controls{display:flex;align-items:center;gap:12px;padding-top:16px}.controls input{flex:1;accent-color:var(--mint)}.caption{display:flex;justify-content:space-between;color:var(--muted);font-size:12px;margin-top:12px;gap:20px}.status{border-left:2px solid var(--mint);padding-left:12px;color:var(--text)!important}.status.rejected{border-color:var(--orange)}.lower{display:grid;grid-template-columns:1fr 1fr;gap:32px;margin-top:42px}h2{font-size:22px;font-weight:500}video{width:100%;border-radius:10px;background:#151e2a}table{width:100%;border-collapse:collapse;font-size:13px}th,td{border-bottom:1px solid #273344;padding:10px 5px;text-align:right}th:first-child,td:first-child{text-align:left}th{font-weight:400;color:var(--muted)}a{color:var(--mint)}footer{margin:35px 0 15px;color:var(--muted);font-size:12px;border-top:1px solid #273344;padding-top:20px}.fine{font-size:12px;color:var(--muted);margin-top:14px}details{margin-top:20px;font-size:13px}summary{cursor:pointer;color:var(--muted)}details p{padding:14px 0}.good{color:var(--mint)}.bad{color:var(--orange)}@media(max-width:850px){main{padding:20px}.intro,.workspace,.lower{grid-template-columns:1fr;gap:20px}.intro{padding-top:25px}.aside{display:grid;grid-template-columns:1fr 1fr;padding:18px}.stats{justify-content:flex-start;gap:40px}.stat strong{font-size:28px}.caption{flex-direction:column;gap:2px}nav span:last-child{font-size:10px}.aside canvas{max-height:220px}}@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto}}
.scene-card{width:220px;text-align:left;padding:6px;display:flex;flex-direction:column;gap:7px}.scene-card img{width:100%;aspect-ratio:16/9;object-fit:cover;border-radius:5px}.scene-card span{padding:0 7px 5px}.run-label{font-size:11px;color:var(--mint);letter-spacing:1px;margin-bottom:10px}.detail-section{display:grid;grid-template-columns:2.4fr 1fr;gap:22px;margin-top:38px;align-items:center}.detail-section h2{font-size:28px;line-height:1.2}.detail-section p{font-size:14px}.method-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin-top:20px}.method-grid figure{margin:0}.method-grid img{width:100%;border-radius:8px}.method-grid figcaption{font-size:13px;margin-top:6px}.film-link{display:inline-block;padding:10px 16px;border:1px solid var(--mint);border-radius:8px;margin-top:18px;text-decoration:none}.scene-description{font-size:16px;margin:0 0 18px;color:var(--text)}[hidden]{display:none!important}@media(max-width:850px){.detail-section{grid-template-columns:1fr}.scene-card{width:calc(50% - 5px)}.method-grid{grid-template-columns:repeat(2,1fr)}}
@media(max-width:520px){.aside{display:block}.aside>div+div{margin-top:22px}.aside canvas{max-height:none}.stats{display:grid;grid-template-columns:1fr 1fr;gap:16px}.stat strong{font-size:25px;white-space:nowrap}}
</style>
<main><nav><span class="logo">bae</span><span>SPARSE OPTIMIZATION · REAL SCENES</span></nav>
<div class="intro"><div><div class="eyebrow">DEPTH ANYTHING 3 → CAMERA REFINEMENT</div><h1>One room.<br>Every view counts.</h1><p>Explore how camera-pose optimization changes a reconstructed room. Drag to compare the same 3D view, or follow the solver step by step.</p><a class="film-link" href="room_refinement.mp4">▶ Watch the 33-second film</a></div><div class="stats"><div class="stat"><strong id="n"></strong><span>DSLR views across the scene</span></div><div class="stat"><strong id="auc"></strong><span>pose AUC @ 5° · higher is better</span></div></div></div>
<div class="scenes" id="scenes" aria-label="Scene selection"></div><p id="sceneDescription" class="scene-description"></p><div class="workspace"><div><div class="compare" id="compare"><img id="before" alt="DA3 reconstruction before camera refinement"><img class="after" id="after" alt="Reconstruction at the selected optimization step"><div class="divider"></div><div class="handle">↔</div><span class="tag left">DA3 / INITIAL</span><span class="tag right" id="tag">BAE / FINAL</span><input class="drag" id="split" type="range" min="0" max="100" value="50" aria-label="Before and after comparison position"></div><div class="controls"><button id="play" aria-label="Play optimization">▶ Play</button><input id="step" type="range" min="0" max="1" value="1" aria-label="Optimization step"><span id="stepLabel"></span></div><div class="caption"><span id="coverage"></span><span>Same depth · Same rendering camera · No synthetic pose noise</span></div></div>
<aside class="aside"><div><h2>Camera poses</h2><canvas id="poses" width="500" height="435" aria-label="Camera positions projected onto the room plane"></canvas><div class="key"><span><b style="background:#ffbd8c"></b>Initial</span><span><b style="background:#71efce"></b>Current</span><span><b style="background:#74839a"></b>COLMAP</span></div></div><div><div id="runLabel" class="run-label"></div><h2 id="stage"></h2><p id="status" class="status"></p><p id="method" style="margin-top:18px"></p><p class="fine">Camera plot uses one fixed similarity alignment for every step. COLMAP is used for evaluation and display only.</p></div></aside></div>
<section id="detailPanel" class="detail-section" hidden><div class="compare" id="detailCompare"><img id="detailBefore" alt="Detail before pose refinement"><img class="after" id="detailAfter" alt="Detail after pose refinement"><div class="divider"></div><div class="handle">↔</div><span class="tag left">DA3 / INITIAL</span><span class="tag right">BAE / RAW RESULT</span><input class="drag" id="detailSplit" type="range" min="0" max="100" value="50" aria-label="Detail before and after position"></div><div><div class="eyebrow">A SECOND VIEWPOINT</div><h2 id="detailTitle"></h2><p id="detailDescription"></p><p class="fine">Drag across the image to inspect the same reconstructed details before and after.</p></div></section>
<details id="methodPanel" hidden><summary>Compare rendered Form D, E and D+E</summary><p>All six raw solver outputs, rendered with the same camera, source images and depth filtering. Open an image to inspect it at full resolution.</p><div class="method-grid" id="methodImages"></div></details>
<div class="lower"><section><h2>Watch the reconstruction change</h2><video id="video" controls playsinline preload="metadata"></video><p class="fine">Explore the reconstructed room and its saved optimizer states. <a id="solverVideo">Watch the full optimization with camera trajectories and AUC.</a></p></section><section><h2>How do the formulations compare?</h2><table><thead><tr><th>Method</th><th>Raw AUC@5</th><th>Returned AUC@5</th><th>Guard</th></tr></thead><tbody id="rows"></tbody></table><p class="fine">D: odometry + pose graph (Open3D), or joint odometry (bae). E: fixed-structure photometric refinement. D+E chains the raw stages before the common guard.</p></section></div>
<details><summary>Inputs, rendering and reproducibility</summary><p id="provenance"></p><p>Raw proposals are reported even when rejected. A photometric guard is not a guarantee of better ground-truth pose accuracy. Surface fusion and filtering use the same settings before and after; no generated imagery or retouching is used.</p><a id="metrics" href="#">Download measured results (JSON)</a></details>
<footer>bae · ScanNet++ DSLR · Depth Anything 3 · Reproducible GPU optimization and rendering</footer></main>
<script>const scenes=DATA;let active=0,playing=false,timer;const $=id=>document.getElementById(id);const labels={da3:'DA3',bae_d:'bae D',bae_e:'bae E',bae_de:'bae D+E',form_d:'Open3D D',form_e:'Open3D E',form_de:'Open3D D+E'};
function drawPose(s,k){let c=$('poses'),ctx=c.getContext('2d');ctx.clearRect(0,0,c.width,c.height);if(!s.poses)return;let sets=[s.poses.initial,s.poses.gt,s.poses.history[k]||s.poses.final];let b=s.poses.bounds;function xy(p){return [25+(p[0]-b[0])/(b[2]-b[0])*450,410-(p[1]-b[1])/(b[3]-b[1])*385]};sets.forEach((pts,i)=>{ctx.strokeStyle=['#ffbd8c66','#74839a55','#71efce99'][i];ctx.fillStyle=['#ffbd8c','#74839a','#71efce'][i];ctx.lineWidth=1;ctx.beginPath();pts.forEach((p,j)=>{let[x,y]=xy(p);j?ctx.lineTo(x,y):ctx.moveTo(x,y)});ctx.stroke();pts.forEach(p=>{let[x,y]=xy(p);ctx.beginPath();ctx.arc(x,y,2,0,Math.PI*2);ctx.fill()})})}
function step(k){let s=scenes[active];$('after').src=s.frames[k];$('step').value=k;let end=k===s.frames.length-1;$('stepLabel').textContent=end?(s.raw?'Raw result':'Final'):k===0?'Initial':`Step ${k}`;$('tag').textContent=end?(s.raw?'BAE / RAW RESULT':'BAE / RETURNED'):k===0?'BAE / INITIAL':`BAE / STEP ${k}`;drawPose(s,k)}
function select(i){playing=false;clearInterval(timer);$('play').textContent='▶ Play';active=i;let s=scenes[i];document.querySelectorAll('#scenes button').forEach((b,j)=>b.setAttribute('aria-pressed',j===i));$('n').textContent=s.views;$('auc').textContent=s.auc;$('before').src=s.before;$('step').max=s.frames.length-1;$('coverage').textContent=`${s.id} · ${s.views} / ${s.registered} registered frames`;$('stage').textContent=s.stage;$('status').textContent=s.status;$('status').className='status'+(s.accepted?'':' rejected');$('method').textContent=s.method;$('video').pause();$('video').src=s.tour||s.video;$('video').poster=s.tour_poster||s.poster;$('solverVideo').href=s.video;$('runLabel').textContent=s.run_label||'';$('sceneDescription').textContent=s.description||'Inspect furniture and room edges as camera refinement aligns the reconstructed surfaces.';$('detailPanel').hidden=!s.detail;if(s.detail){$('detailBefore').src=s.detail.before;$('detailAfter').src=s.detail.after;$('detailTitle').textContent=s.detail.title;$('detailDescription').textContent=s.detail.description;}$('methodPanel').hidden=!s.formulations;$('methodImages').innerHTML=(s.formulations||[]).map(m=>`<figure><a href="${m.image}"><img loading="lazy" src="${m.image}" alt="${m.label} raw reconstruction"></a><figcaption>${m.label} · raw AUC@5 ${m.auc.toFixed(2)}</figcaption></figure>`).join('');$('metrics').href=s.metrics;$('provenance').textContent=s.provenance;$('rows').innerHTML=s.rows.map(r=>`<tr><td>${r[0]}</td><td>${r[1]}</td><td>${r[2]}</td><td class="${r[3]==='accept'?'good':r[3]==='reject'?'bad':''}">${r[3]}</td></tr>`).join('');step(s.frames.length-1)}
scenes.forEach((s,i)=>{let b=document.createElement('button');b.className='scene-card';let img=document.createElement('img');img.src=s.frames[s.frames.length-1];img.alt='';let label=document.createElement('span');label.textContent=s.title;b.append(img,label);b.onclick=()=>select(i);$('scenes').append(b)});$('detailSplit').oninput=e=>$('detailCompare').style.setProperty('--split',e.target.value+'%');$('split').oninput=e=>$('compare').style.setProperty('--split',e.target.value+'%');$('step').oninput=e=>step(+e.target.value);$('play').onclick=()=>{playing=!playing;clearInterval(timer);$('play').textContent=playing?'Ⅱ Pause':'▶ Play';if(playing){step(0);timer=setInterval(()=>{let k=+$('step').value+1;if(k>=scenes[active].frames.length){playing=false;clearInterval(timer);$('play').textContent='▶ Replay';return}step(k)},220)}};select(0);
</script></html>'''


def build(args):
    dest=args.dest;dest.mkdir(parents=True,exist_ok=True);scenes=[]
    for source in args.scenes:
        folder=Path(source);manifest=folder/'renders/gallery.json'
        if not manifest.exists():raise FileNotFoundError(manifest)
        scene=json.loads(manifest.read_text());sub=dest/scene['id'];sub.mkdir(exist_ok=True)
        # Reference comparisons may finish after the images have rendered.
        latest=json.loads((folder/'metrics.json').read_text())['variants']
        scene['run_label']='GIANT 1.1 · ambient gradients' if json.loads((folder/'metrics.json').read_text()).get('config',{}).get('ambient_grad')=='1' else 'Historical showcase run · before ambient-gradient correction'
        keys=['da3','bae_d','bae_e','bae_de','form_d','form_e','form_de']
        for row,key in zip(scene['rows'],keys):
            if key in latest and 'auc@5' in latest[key]:
                value=latest[key];raw=latest.get(key+'_raw',value)
                row[1:]=[f'{raw["auc@5"]*100:.2f}',f'{value["auc@5"]*100:.2f}',
                         '—' if key=='da3' else 'accept' if value['accepted'] else 'reject']
        for name in ['before','video','poster','metrics']:
            src=folder/scene[name]
            if name=='before':
                # PNG is globally gitignored in this repository. Keep the
                # portable gallery complete when added to version control.
                target=sub/'before.webp';Image.open(src).save(target,lossless=True)
            else:
                target=sub/src.name;shutil.copy2(src,target)
            scene[name]=f'{scene["id"]}/{target.name}'
        def asset(name):
            src=folder/name;target=sub/src.name;shutil.copy2(src,target)
            return f'{scene["id"]}/{target.name}'
        for name in ['tour','tour_poster']:
            if name in scene:scene[name]=asset(scene[name])
        if scene.get('detail'):
            for name in ['before','after']:scene['detail'][name]=asset(scene['detail'][name])
        for method in scene.get('formulations',[]):method['image']=asset(method['image'])
        for name in ['input.json','renders/render.json','renders/story.json','renders/detail_comparison.jpg']:
            if (folder/name).exists():asset(name)
        frames=[]
        for i,name in enumerate(scene['frames']):
            src=folder/name;target=sub/f'step_{i:03d}{src.suffix}';shutil.copy2(src,target);frames.append(f'{scene["id"]}/{target.name}')
        scene['frames']=frames;scenes.append(scene)
    tours=[dest/s['tour'] for s in scenes if s.get('tour')]
    page=PAGE
    if tours:
        import imageio_ffmpeg
        with tempfile.TemporaryDirectory() as directory:
            listing=Path(directory)/'chapters.txt'
            listing.write_text(''.join("file '"+str(p.resolve()).replace("'", "'\\''")+"'\n" for p in tours))
            subprocess.run([imageio_ffmpeg.get_ffmpeg_exe(),'-y','-f','concat','-safe','0',
                            '-i',str(listing),'-c','copy','-movflags','+faststart',
                            str(dest/'room_refinement.mp4')],check=True,capture_output=True)
        seconds=round(sum(imageio_ffmpeg.count_frames_and_secs(str(p))[1] for p in tours))
        page=page.replace('33-second film',f'{seconds}-second film')
    else:
        page=page.replace('<a class="film-link" href="room_refinement.mp4">▶ Watch the 33-second film</a>','')
    (dest/'index.html').write_text(page.replace('DATA',json.dumps(scenes).replace('</','<\\/')))
    print(dest/'index.html')

if __name__=='__main__':
    p=argparse.ArgumentParser(description=__doc__);p.add_argument('scenes',nargs='+');p.add_argument('--dest',type=Path,default=Path('examples/rgbd_pose_refine/docs/showcase'))
    build(p.parse_args())
